"""
The Nonlinearity Index: use-case comparison data.

These are tendencies, not rules. Each entry says which activations practitioners tend to pick
for a kind of task or architecture, and which *properties* make them a good fit. No activation
is exclusive to a domain.

Fields:
  slug, title, area     area is one of AREAS
  arch                  architectures where this applies
  picks                 list of (function slug, role) pairs; slugs must exist in catalog.py
  props                 keys from PROPS that matter for this use case
  why                   the reasoning
  caveat                what to watch out for
  examples              well-known models or systems (optional)
"""

AREAS = ["Language", "Vision", "Sequences & time series", "Generative", "Science & simulation",
         "Graphs & tabular", "Control", "Efficiency", "Outputs"]

PROPS = [
    ("smooth", "Smooth gradients", "Differentiable everywhere, with no kinks, so gradients change gradually."),
    ("sparse", "Sparsity", "Outputs exact zeros for many inputs, so only some units are active."),
    ("bounded", "Bounded output", "The output stays inside a fixed interval, however large the input."),
    ("zero-centred", "Zero-centred", "Outputs take both signs and average near zero."),
    ("no-dead", "No dead units", "Negative inputs still get a gradient, so units can't permanently switch off."),
    ("gating", "Multiplicative gating", "One signal scales another, letting the network choose what passes."),
    ("cheap", "Cheap to compute", "No exponentials or divisions; piecewise-linear or polynomial."),
    ("quant", "Quantisation-friendly", "Bounded and piecewise-linear, so it survives low-precision integer arithmetic."),
    ("higher-deriv", "Usable higher derivatives", "Second and higher derivatives are non-zero and smooth."),
    ("periodic", "Periodic bias", "Oscillates, which helps represent repeating or high-frequency signals."),
    ("self-norm", "Self-normalising", "Keeps activations near zero mean and unit variance without a normalisation layer."),
    ("prob", "Probabilistic output", "Outputs can be read directly as probabilities."),
]

